import{_ as n,C as o,o as d,c as s,j as a,E as e,a as r,a3 as l}from"./chunks/framework.C6R8kWFE.js";const z=JSON.parse(`{"title":"1-hafta (Mentor)","description":"","frontmatter":{"title":"1-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"n":1,"bob":"I-bob · Kompyuter savodxonligi va arxitekturasi","lessons":[{"g":1,"title":"Zamonaviy kompyuterlar va ularning arxitekturasi","lead":"Har kuni foydalanadigan kompyuteringiz aslida qanday ishlaydi? Ushbu darsda kompyuterning «ichki dunyosi»ga sayohat qilamiz: protsessor, tezkor xotira, fon Neyman arxitekturasi va kompyuterning yashirin texnik parametrlarini ochishni o'rganamiz.","link":"/mentor/8-sinf-cs/hafta-01/dars-1","slide":"/slaydlar/8-sinf-cs/hafta-01/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-01/dars-1-test.html"},{"g":2,"title":"Operatsion tizimlar va Windows muhitida ishlash","lead":"Kompyuterni yoqqaningizda ekranda jilvalanadigan chiroyli ish stoli va derazalar ortida qanday kuch turibdi? Ushbu darsda kompyuterning «boshqaruvchi yuragi» bo'lgan operatsion tizimlar, Windows 10/11 imkoniyatlari, oynalarni bo'lish va dasturlarni professional boshqarishni o'rganamiz.","link":"/mentor/8-sinf-cs/hafta-01/dars-2","slide":"/slaydlar/8-sinf-cs/hafta-01/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-01/dars-2-test.html"},{"g":3,"title":"Axborot o‘lchov birliklari va fayl turlari. Windows operatsion tizimida fayl hamda papkalar yaratish. Tezkor tugmalar (Hot keys)","lead":"Nega kompyuterda 1 kilobayt 1000 emas, balki 1024 baytga teng? Har bir fayl ortida qanday kengaytma yashiringan va nima uchun professional dasturchilar sichqonchadan ko'ra tezkor tugmalarni (Hot keys) afzal ko'rishadi? Ushbu darsda axborot hisob-kitoblari va fayllarni boshqarish sirlarini o'rganamiz.","link":"/mentor/8-sinf-cs/hafta-01/dars-3","slide":"/slaydlar/8-sinf-cs/hafta-01/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-01/dars-3-test.html"}],"test":"/slaydlar/8-sinf-cs/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-01/index.md","filePath":"mentor/8-sinf-cs/hafta-01/index.md"}`),h={name:"mentor/8-sinf-cs/hafta-01/index.md"},c={class:"blk"},y={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},g={class:"blk"},u={id:"baholash-mezoni",tabindex:"-1"};function m(k,t,x,b,v,p){const i=o("Icon");return d(),s("div",null,[a("div",c,[a("h2",y,[e(i,{name:"house"}),t[0]||(t[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),t[2]||(t[2]=l('<p>Har bir vazifa 20–30 daqiqa vaqt oladi. Vazifalar daftarda yoki kompyuterda alohida papkada saqlanadi.</p><h2 id="_1-dars-uchun-zamonaviy-kompyuterlar-va-ularning-arxitekturasi" tabindex="-1">1-dars uchun (Zamonaviy kompyuterlar va ularning arxitekturasi) <a class="header-anchor" href="#_1-dars-uchun-zamonaviy-kompyuterlar-va-ularning-arxitekturasi" aria-label="Permalink to &quot;1-dars uchun (Zamonaviy kompyuterlar va ularning arxitekturasi)&quot;">​</a></h2><p><strong>1-topshiriq: «Mening kompyuterim pasporti»</strong></p><ol><li>O&#39;zingiz foydalanadigan kompyuter (yoki maktab kompyuteri) turini aniqlang (Desktop PC, noutbuk yoki monoblok).</li><li><code>Ctrl + Shift + Esc</code> (Task Manager) yoki <code>Win + R</code> → <code>msinfo32</code> orqali protsessor (CPU) modeli va uning takt chastotasini yozing.</li><li>Operativ xotira (RAM) hajmini aniqlang.</li><li>Doimiy xotira diskining turi (SSD yoki HDD) va umumiy hajmini yozing.</li><li>Kompyuteringizga ulangan 2 ta kiritish va 2 ta chiqarish qurilmasi nomini daftaringizga qayd eting.</li></ol><p><strong>Kutiladigan natija:</strong> Kompyuterning barcha texnik parametrlari aniq ko&#39;rsatilgan qisqa «texnik pasport».</p><h2 id="_2-dars-uchun-operatsion-tizimlar-va-windows-muhitida-ishlash" tabindex="-1">2-dars uchun (Operatsion tizimlar va Windows muhitida ishlash) <a class="header-anchor" href="#_2-dars-uchun-operatsion-tizimlar-va-windows-muhitida-ishlash" aria-label="Permalink to &quot;2-dars uchun (Operatsion tizimlar va Windows muhitida ishlash)&quot;">​</a></h2><p><strong>2-topshiriq: «Windows sozlamalari va tezkor boshqaruv»</strong></p><ol><li>Klaviaturadagi <code>Win + I</code> tugmalarini bosib, Sozlamalar oynasini oching. Kompyuteringizdagi Windows versiyasi va nashrini (masalan, Windows 11 Pro) yozib oling.</li><li>Ikkita dasturni (masalan, brauzer va Bloknot) ochib, <code>Win + Chapga strelka</code> va <code>Win + O&#39;ngga strelka</code> orqali ularni ekranga 50/50 qilib yonma-yon joylashtiring.</li><li>Klaviaturadagi <code>Alt + Tab</code>, <code>Win + D</code>, <code>Win + E</code> tugmalarini kamida 3 marta sinab ko&#39;ring va ularning har biri qanday natija berganini daftaringizga 1 jumlada yozing.</li><li><code>Settings</code> → «Installed apps» bo&#39;limiga kirib, kompyuteringizdagi 3 ta eng katta hajmli dasturning nomi va hajmini (MB yoki GB) yozing.</li></ol><p><strong>Kutiladigan natija:</strong> Windows tezkor tugmalari bo&#39;yicha amaliy tajriba va o&#39;rnatilgan dasturlar tahlili.</p><h2 id="_3-dars-uchun-axborot-o-lchov-birliklari-fayl-turlari-va-tezkor-tugmalar" tabindex="-1">3-dars uchun (Axborot o‘lchov birliklari, fayl turlari va tezkor tugmalar) <a class="header-anchor" href="#_3-dars-uchun-axborot-o-lchov-birliklari-fayl-turlari-va-tezkor-tugmalar" aria-label="Permalink to &quot;3-dars uchun (Axborot o‘lchov birliklari, fayl turlari va tezkor tugmalar)&quot;">​</a></h2><p><strong>3-topshiriq: «Axborot hisobi va papkalar daraxti»</strong></p><ol><li>Quyidagi axborot hisob-kitobini daftaringizda bajaring: <ul><li>$8 \\text{ GB}$ hajmli fleshkaga har biri $4 \\text{ MB}$ bo&#39;lgan qo&#39;shiqlardan nechta sig&#39;adi? ($8 \\text{ GB} = 8 \\times 1024 \\text{ MB}$).</li></ul></li><li>Kompyuteringizning <code>Documents</code> papkasida <code>CS_Foundation</code> nomli papka oching (<code>Ctrl + Shift + N</code>).</li><li>Uning ichida <code>Hujjatlar</code> va <code>Rasmlar</code> nomli ikkita ichki papka yarating.</li><li><code>Hujjatlar</code> ichida <code>reja.txt</code> faylini yarating, <code>Ctrl+C</code> va <code>Ctrl+V</code> orqali nusxasini oling, so&#39;ngra nusxasini <code>F2</code> bilan <code>reja_nusxa.txt</code> deb o&#39;zgartiring.</li><li><code>reja_nusxa.txt</code> faylini <code>Delete</code> bilan Savatchaga tashlang va Savatchadan «Restore» amali orqali qayta tiklab ko&#39;ring.</li></ol><p><strong>Kutiladigan natija:</strong> To&#39;g&#39;ri matematik hisoblash va kompyuterda yaratilgan tartibli papkalar strukturasi.</p><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>Keyingi dars boshida (10 daqiqalik takrorlashda) 1–2 nafar o&#39;quvchining kompyuter pasporti va hisoblash natijalarini doskada ko&#39;rib chiqing. Tezkor tugmalar (<code>Ctrl+C</code>, <code>Ctrl+V</code>, <code>Win+E</code>, <code>Alt+Tab</code>) o&#39;quvchilar refleksiga aylanganiga ishonch hosil qiling.</p>',15))]),a("div",g,[a("h2",u,[e(i,{name:"list-checks"}),t[3]||(t[3]=r(" Baholash mezoni ",-1)),t[4]||(t[4]=a("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),t[5]||(t[5]=l('<p>Dasturdagi mezonlarga asoslangan (100 ballik shkala): <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><p>Dasturda joriy nazorat (amaliy mashg&#39;ulotlar, darsdagi faollik, tezkor savol-javoblar va uy vazifasi) o&#39;quv jarayoni davomida o&#39;tkaziladi. Quyida 1-haftaning 3 ta darsi bo&#39;yicha har bir o&#39;quvchi ishtirokini qayd etish uchun baholash jadvali keltirilgan.</p><h2 id="mezonlar-har-bir-dars-uchun" tabindex="-1">Mezonlar (har bir dars uchun) <a class="header-anchor" href="#mezonlar-har-bir-dars-uchun" aria-label="Permalink to &quot;Mezonlar (har bir dars uchun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th style="text-align:center;">Max ball</th><th>Tavsif</th></tr></thead><tbody><tr><td>Nazariya va tushunchalar</td><td style="text-align:center;">30</td><td>Kompyuter tuzilishi, fon Neyman arxitekturasi, OT va axborot birliklarini to&#39;g&#39;ri tushuntirib bera oladi</td></tr><tr><td>Amaliy ko&#39;nikmalar</td><td style="text-align:center;">30</td><td>Task Manager, msinfo32, dxdiag, oynalarni bo&#39;lish (Snap) va papkalar yaratish amallarini to&#39;g&#39;ri bajaradi</td></tr><tr><td>Tezkor tugmalar va texnika</td><td style="text-align:center;">20</td><td>Klaviaturadan to&#39;g&#39;ri foydalanadi (Ctrl+C, Ctrl+V, F2, Win+E, Win+I, Alt+Tab)</td></tr><tr><td>Uyga vazifa</td><td style="text-align:center;">20</td><td>Uy vazifasi to&#39;liq, vaqtida va aniq bajarilgan</td></tr><tr><td><strong>Jami</strong></td><td style="text-align:center;"><strong>100</strong></td><td></td></tr></tbody></table><hr><h2 id="_1-dars-kompyuter-arxitekturasi-va-apparat-qismlari" tabindex="-1">1-dars (Kompyuter arxitekturasi va apparat qismlari) <a class="header-anchor" href="#_1-dars-kompyuter-arxitekturasi-va-apparat-qismlari" aria-label="Permalink to &quot;1-dars (Kompyuter arxitekturasi va apparat qismlari)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Tezkor tugma /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_2-dars-operatsion-tizimlar-va-windows" tabindex="-1">2-dars (Operatsion tizimlar va Windows) <a class="header-anchor" href="#_2-dars-operatsion-tizimlar-va-windows" aria-label="Permalink to &quot;2-dars (Operatsion tizimlar va Windows)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Tezkor tugma /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_3-dars-axborot-o-lchov-birliklari-va-fayllar" tabindex="-1">3-dars (Axborot o&#39;lchov birliklari va fayllar) <a class="header-anchor" href="#_3-dars-axborot-o-lchov-birliklari-va-fayllar" aria-label="Permalink to &quot;3-dars (Axborot o&#39;lchov birliklari va fayllar)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Tezkor tugma /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_1-hafta-yakuni" tabindex="-1">1-hafta yakuni <a class="header-anchor" href="#_1-hafta-yakuni" aria-label="Permalink to &quot;1-hafta yakuni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">1-dars</th><th style="text-align:center;">2-dars</th><th style="text-align:center;">3-dars</th><th style="text-align:center;">O&#39;rtacha ball</th><th style="text-align:center;">Yakuniy baho</th><th>Izoh va tavsiyalar</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr></tbody></table><hr><h2 id="hafta-xulosasi-va-keyingi-haftaga-ko-prik" tabindex="-1">Hafta xulosasi va keyingi haftaga ko&#39;prik <a class="header-anchor" href="#hafta-xulosasi-va-keyingi-haftaga-ko-prik" aria-label="Permalink to &quot;Hafta xulosasi va keyingi haftaga ko&#39;prik&quot;">​</a></h2><p><strong>1-haftada o&#39;rganilgan asosiy kompetensiyalar:</strong></p><ul><li>Kompyuter turlari (Desktop, Noutbuk, Server, Superkompyuter) va fon Neyman arxitekturasi;</li><li>Protsessor (CPU), operativ xotira (RAM), doimiy disklar (SSD va HDD) farqi;</li><li>Operatsion tizim (OT) tushunchasi, Windows, Linux, macOS, Android, iOS;</li><li>Windows ish stoli, oynalarni boshqarish (Snap layouts: <code>Win + strelkalar</code>), tizim sozlamalari (<code>Win + I</code>);</li><li>Axborot o&#39;lchov birliklari (Bit, Bayt, KB, MB, GB, TB) va 1024 karrali hisob-kitoblar;</li><li>Fayl turlari, kengaytmalar (<code>.txt</code>, <code>.docx</code>, <code>.png</code>, <code>.py</code>, <code>.exe</code>), papkalar daraxti va asosiy tezkor tugmalar (<code>Ctrl+C</code>, <code>Ctrl+V</code>, <code>Ctrl+X</code>, <code>Ctrl+Z</code>, <code>F2</code>, <code>Win+E</code>).</li></ul><p><strong>Keyingi hafta (2-hafta, 4–6-darslar):</strong></p><ul><li><em>4-dars:</em> Kompyuterning asosiy va qo&#39;shimcha qurilmalari (printer, skaner, veb-kamera, proyektor).</li><li><em>5-dars:</em> Internet, brauzerlar va elektron pochta bilan ishlash (Chrome, Edge, qidiruv tizimlari, email ochish va xat yuborish).</li><li><em>6-dars:</em> Kompyuter xavfsizligi va antivirus dasturlari (viruslar, parollar, 2FA, ma&#39;lumotlarni himoya qilish). Bu mavzular 1-bobning mantiqiy yakunlanishiga xizmat qiladi va o&#39;quvchilarni zamonaviy raqamli dunyoda xavfsiz ishlashga tayyorlaydi.</li></ul>',22))])])}const q=n(h,[["render",m]]);export{z as __pageData,q as default};
